  ('1fb40457-f235-5192-990c-c7df1f1012c0', null, (select id from public.skills where slug = 'read-g10-argument-evidence'), null, 'medium',
   $q$Why is it relevant that cargo did not recover after the autumn rains of 1871?$q$, $q$[{"text":"It proves that the rains damaged the canal's locks beyond repair.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"It suggests that merchants were waiting for the railroad to open.","is_correct":false,"misconception_token":"misreads-detail"},{"text":"If low water were the cause, traffic should have returned with the water.","is_correct":true},{"text":"It shows that the drought lasted much longer than two months.","is_correct":false,"misconception_token":"contradicts-text"}]$q$::jsonb, $q$If low water were the cause, traffic should have returned with the water.$q$, $q$Once water returned, "boats could travel the full length again," yet cargo kept falling, which suggests something besides low water was keeping shippers away. The railroad had opened in 1858, so merchants were not waiting for it.$q$, 'draft', 'b116a008-5aaa-5731-ac44-593527db3f0b')
